    while row_start <= row_stop and col_start <= col_stop:
        for i in range(col_start, col_stop + 1):
            print(arr[row_start][i], end=' ')
        row_start += 1
        for i in range(row_start, row_stop + 1):
            print(arr[i][col_stop], end=' ')
        col_stop -= 1
        if row_start <= row_stop:
