    # Create a dictionaries for strings
    string1_dict = {}
    string2_dict = {}

    # Add the chars from each string to the dictionaries
    for char in string1:
        if char not in string1_dict:
            string1_dict[char] = 1
        else:
            string1_dict[char] += 1

    for char in string2:
        if char not in string2_dict:
