    int top(); 
}; 

void Stack::push(int data) 
{ 
    // inserting an element 
    // on the top of the stack 
    v.push_back(data); 
} 

bool Stack::empty() 
{ 
    // checking if the stack is empty 
    return v.size() == 0; 
} 

void Stack::pop() 
{ 
    // removing element 
    // from the top of the stack 
    if (!empty()) 
    { 
        v.pop_back(); 
    } 
} 

int Stack::top() 
{ 
    // returns the top element 
    // of the stack 
    return v.back(); 
}

def factor_list(number):    
    factors = []

    i = 2
    while i * i <= number:
        if number % i:
            i += 1
        else:
            number //= i
            factors.append(i)
    if number > 1:
        factors.append(number)

    return factors

